/**
 *  Generated by `contract-codegen` from the checked-in contract schemas.
 *
 *  This file is the Node client's walk over every operation, against a real supervisor.
 *
 *  Do not edit by hand: change the contracts, regenerate with `just
 *  generate-clients`, and commit what that writes.
 *
 * Every method this client exposes is driven against the **real**
 * printobserver supervisor — the program this repository builds, over the
 * OctoPrint `just octoprint-up` started, holding a print and a stored image
 * the supervisor's own ingress opened. A recording proxy sits in front of
 * it, so what each assertion is against is the request that supervisor
 * received and the answer it actually sent.
 *
 * The order is the one a real machine admits: a printer is a state machine
 * and the policy refuses an action that is not valid from where it is. It
 * ends with the machine printing, where the bring-up left it.
 */

import { afterAll, beforeAll, expect, test } from "bun:test";
import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Client } from "../src/client.ts";
import type { JobManifest } from "../src/contract.ts";
import { Rejected } from "../src/surface.ts";
import { Recording, ready, same } from "./live.ts";
import { SETUP_TIMEOUT_MS, Standing, type Supervisor } from "./world.ts";

/** The reason every mutating call of this walk carries. */
const REASON = "a generated walk is asking";

let standing: Standing;
let world: Supervisor;

beforeAll(async () => {
  standing = await Standing.standing(mkdtempSync(join(tmpdir(), "printobserver-live-")));
  world = standing.at;
}, SETUP_TIMEOUT_MS);

afterAll(async () => {
  await standing.stop();
});

/**
 * The manifest this walk writes and starts a print under.
 *
 * It narrows nothing: what the walk needs is every adjustment the envelope
 * allows to be answered, and a narrowing here would refuse one for a reason
 * that is not what this walk is about.
 */
function manifest(at: Supervisor): JobManifest {
  return {
    file_name: at.file_name,
    material: "PLA",
    nozzle_diameter_mm: 0.4,
    slicer_profile: "the walk over every operation",
    allowed: {},
    metadata: {},
  };
}

/** `status`, answered by a real supervisor. */
async function stepStatus(client: Client, proxy: Recording) {
  await ready(client, world.print_id, "");

  const answered = await client.status(world.print_id);

  const seen = proxy.last();
  expect(seen.method).toBe("GET");
  expect(seen.target).toBe(`/v1/prints/${world.print_id}/status`);
  expect(seen.status).toBe(200);
  expect(seen.body).toBe("");
  same("status", answered, seen.answer);
}

