test("every method is answered by a real supervisor", async () => {
  await using proxy = new Recording(world.server);
  const client = new Client({ server: proxy.url, actor: "operator" });

  await stepStatus(client, proxy);
  await stepContext(client, proxy);
  await stepImage(client, proxy);
  await stepManifestSet(client, proxy);
  await stepManifestGet(client, proxy);
  await stepHistory(client, proxy);
  await stepCancel(client, proxy);
  await stepStartPrint(client, proxy);
  await stepSetFeedrateFactor(client, proxy);
  await stepSetFlowrateFactor(client, proxy);
  await stepSetFanPercent(client, proxy);
  await stepSetToolTargetC(client, proxy);
  await stepSetBedTargetC(client, proxy);
  await stepAcknowledgeFailure(client, proxy);
  await stepPause(client, proxy);
  await stepResume(client, proxy);

  expect(proxy.calls()).toBeGreaterThanOrEqual(16);
}, 900_000);

/** `cancel`, refused by a real supervisor's own policy. */
async function refusedCancel(client: Client, proxy: Recording) {
  const refused = await client.cancel(world.print_id, REASON).catch((raised: unknown) => raised);

  expect(refused).toBeInstanceOf(Rejected);
  expect((refused as Rejected).reason).toHaveProperty("actor_may_not_request");
  const seen = proxy.last();
  expect(seen.status).toBe(409);
  same("cancel", (refused as Rejected).answer, seen.answer);
}

